import { strict as assert } from "node:assert";
import { writeFileSync } from "node:fs";
import { buildPdfFromJpegs } from "../src/exporters.js";

const onePixelJpeg = "";

const pdfBlob = buildPdfFromJpegs([{ dataUrl: `data:image/jpeg;base64,${onePixelJpeg}`, width: 1, height: 1 }], 595, 842);
const pdfBytes = new Uint8Array(await pdfBlob.arrayBuffer());
const pdfText = new TextDecoder("latin1").decode(pdfBytes);

assert.equal(pdfText.slice(0, 8), "%PDF-1.4");
assert.match(pdfText, /\/Type \/Catalog/);
assert.match(pdfText, /\/Type \/Pages/);
assert.match(pdfText, /\/Count 1/);
assert.match(pdfText, /startxref/);

if (process.env.EXPORT_VALIDATION_PATH) writeFileSync(process.env.EXPORT_VALIDATION_PATH, pdfBytes);
console.log(`PDF writer ok: ${pdfBytes.length} bytes`);
